{"results": [{"id": "hp_doc_c887c8ff93f15566b2b0828cfa4d56f5f4c9823b8e03800a3964d3e50bf6c1e1", "title": "Collective Soul", "text": "Collective Soul is an American rock band originally from Stockbridge, Georgia. Now based in Atlanta, the group consists of lead vocalist Ed Roland, rhythm guitarist Dean Roland, bassist Will Turpin, drummer Johnny Rabb and lead guitarist Jesse Triplett.", "score": 31.6446}, {"id": "hp_doc_1b14f1db168d1e3e9bcfb36daebedc8049cc2b669231a5fa4246122eaecc6f84", "title": "Smashing Young Man", "text": "\"Smashing Young Man\" is a song by the American band Collective Soul. It is the third single from their second studio album \"Collective Soul\". The song was written as an insult to Smashing Pumpkins lead singer, Billy Corgan, who accused Collective Soul of plagiarizing music.", "score": 27.4815}, {"id": "hp_doc_3b0b5eb94c03f3b39adf9d6393d229f03b28a473b9119071c1172c7614addd6b", "title": "Ross Childress", "text": "Ross Childress (born September 8, 1971) is an American musician. He was the original lead guitarist and co-songwriter for the rock band Collective Soul.", "score": 26.5967}], "remaining_searches": 2}
